<?php require 'config.php'; require_login(); $title='Important Academic Dates'; $today=date('Y-m-d'); $q=$pdo->prepare("SELECT * FROM important_dates WHERE event_date>=? ORDER BY event_date ASC LIMIT 30");$q->execute([$today]);$rows=$q->fetchAll(); require 'header.php'; ?><section class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC CALENDAR</span><h2>Important Dates</h2><p class="muted">Upcoming enrollment, examination, and academic dates.</p></div></div><?php if(!$rows):?><div class="info-box">No upcoming academic dates have been posted.</div><?php else:?><div class="date-list"><?php foreach($rows as $r):?><div class="date-item"><div class="date-box"><b><?=date('M',strtotime($r['event_date']))?></b><strong><?=date('d',strtotime($r['event_date']))?></strong></div><div><span class="badge pending"><?=e($r['event_type'])?></span><h3><?=e($r['title'])?></h3><p><?=e($r['description']?:'No additional details.')?></p></div></div><?php endforeach;?></div><?php endif;?></section><?php require 'footer.php'; ?>
